87:                 starts = currentTokenCounters.starts
88:             }
89:         }

142:     private boolean checkRevenue(Double revenue, String currency) {
143:         if (revenue != null) {
144:             if (revenue < 0.0) {
145:                 logger.error("Invalid amount %.5f", revenue);
146:                 return false;
147:             }
148: 
149:             if (currency == null) {
150:                 logger.error("Currency must be set with revenue");
151:                 return false;
152:             }
153:             if (currency.equals("")) {
154:                 logger.error("Currency is empty");
155:                 return false;
156:             }
157: 
158:         } else if (currency != null) {
159:             logger.error("Revenue must be set with currency");
160:             return false;
161:         }
162:         return true;
163:     }
164: }
